"""Local pretrained-language feasibility only; no architecture/learning claim."""
from pathlib import Path
import argparse,json,time,hashlib,subprocess,resource,importlib.metadata
import torch
from transformers import AutoTokenizer,AutoModelForCausalLM

def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
    p=argparse.ArgumentParser();p.add_argument('--model',type=Path,required=True);p.add_argument('--transformers-repo',type=Path,required=True);p.add_argument('--out',type=Path,required=True);a=p.parse_args();torch.set_num_threads(1);torch.manual_seed(1531);source=json.loads((a.model/'source_identity.json').read_text());assert sha(a.model/'model.safetensors')==source['weights_sha256'];head=subprocess.check_output(['git','rev-parse','HEAD'],cwd=a.transformers_repo,text=True).strip();assert head=='052e652d6d53c2b26ffde87e039b723949a53493'
