    with torch.no_grad():
        for prompt in prompts:
            text=tokenizer.apply_chat_template([dict(role='user',content=prompt)],tokenize=False,add_generation_prompt=True);inputs=tokenizer(text,return_tensors='pt');token_lists.append(inputs['input_ids'][0].tolist());start=time.perf_counter();out=model(**inputs,use_cache=True);seconds=time.perf_counter()-start;assert torch.isfinite(out.logits).all();last_logits.append(out.logits[:,-1].clone());cache=out.past_key_values.to_legacy_cache() if hasattr(out.past_key_values,'to_legacy_cache') else out.past_key_values;cache_bytes.append(sum(t.numel()*t.element_size() for layer in cache for t in layer));start=time.perf_counter();generated=model.generate(**inputs,max_new_tokens=8,do_sample=False,temperature=None,top_p=None,top_k=None,pad_token_id=tokenizer.eos_token_id);decoded=tokenizer.decode(generated[0,inputs['input_ids'].shape[1]:],skip_special_tokens=True);rows.append(dict(prompt=prompt,input_tokens=inputs['input_ids'].shape[1],prefill_seconds=seconds,generation_seconds=time.perf_counter()-start,new_tokens=generated.shape[1]-inputs['input_ids'].shape[1],output=decoded))
    assert sorted(token_lists[0])==sorted(token_lists[1]);assert not torch.equal(last_logits[0],last_logits[1]);assert model.lm_head.weight.data_ptr()==model.model.embed_tokens.weight.data_ptr();a.out.mkdir(parents=True,exist_ok=True)
